<?php namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; class AnnouncementRequest extends FormRequest {public function authorize():bool{return $this->user()?->role?->value==='organizer'&&$this->route('event')->organizer_id===$this->user()->id;}public function rules():array{return ['message'=>['required','string','max:2000']];}public function messages():array{return ['message.required'=>'نص الإعلان مطلوب.'];}}
